// [의사코드] 저장된 배치·반입 명세를 따라 모델/시각 배치와 검수 결과를 재현한다.
// [코딩]
// Pseudocode: copy verified derivatives to classified model folders, create URP materials,
// then save Collider-free prefabs and source manifests without editing gameplay assets.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class ImportRemaining {
 static string W=>PlacementSession.Work;
 static string Destination(string name){string category=name.StartsWith("Env_")?"Environment":"Props";string floor=name.Contains("LaboratoryWorkbench")||name.Contains("SteelColumn")||name.Contains("SteelIBeam")?"Common":name.Contains("ExteriorCorner")||name.Contains("LoadingShutter")||name.Contains("PalletStorageRack")?"1F":name.Contains("ExhaustFan")||name.Contains("MaintenanceToolCart")?"B4":name.Contains("GasCylinderRack")?"B3":"B2";return PlacementSession.Root+"05.Model/"+category+"/"+floor;}
 static void Texture(string path,bool normal){var t=(TextureImporter)AssetImporter.GetAtPath(path);t.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;t.sRGBTexture=!normal;t.maxTextureSize=2048;t.mipmapEnabled=true;t.isReadable=false;t.textureCompression=TextureImporterCompression.CompressedHQ;t.SaveAndReimport();}
 public static string Pending(){var reportPath=Path.Combine(W,"unity_import_facts.json");var reports=File.Exists(reportPath)?JArray.Parse(File.ReadAllText(reportPath)):new JArray();int done=0;foreach(var m in Directory.GetFiles(Path.Combine(W,"prepared"),"manifest.json",SearchOption.AllDirectories)){var a=JObject.Parse(File.ReadAllText(m));string name=(string)a["name"];string verified=Path.Combine(Path.GetDirectoryName(m),"fbx_verification.json");if(!File.Exists(verified)||!(bool)JObject.Parse(File.ReadAllText(verified))["accepted"])continue;var previous=reports.FirstOrDefault(x=>(string)x["name"]==name);if(previous!=null&&(string)previous["derivativeSha256"]==(string)a["fbxSha256"])continue;if(previous!=null)reports.Remove(previous);if(a["meshes"].Any(x=>(int)x["final"]["strictCrossingPairs"]!=0||(int)x["final"]["boundaryEdges"]!=0||(int)x["final"]["overusedEdges"]!=0))continue;
 string target=Destination(name);Directory.CreateDirectory(target+"/Materials");Directory.CreateDirectory(target+"/Textures");string modelPath=target+"/"+name+".fbx";File.Copy((string)a["fbx"],modelPath,true);foreach(JObject t in a["textures"]){string path=target+"/Textures/"+Path.GetFileName((string)t["path"]);File.Copy((string)t["path"],path,true);t["assetPath"]=path;}
 AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var importer=(ModelImporter)AssetImporter.GetAtPath(modelPath);importer.materialImportMode=ModelImporterMaterialImportMode.None;importer.importAnimation=false;importer.importCameras=false;importer.importLights=false;importer.importNormals=ModelImporterNormals.Import;importer.importTangents=ModelImporterTangents.CalculateMikk;importer.meshCompression=ModelImporterMeshCompression.Off;importer.isReadable=false;importer.addCollider=false;importer.SaveAndReimport();foreach(JObject t in a["textures"])Texture((string)t["assetPath"],(string)t["semantic"]=="Normal");
 var materials=new List<Material>();foreach(JObject sm in a["materials"]){string matPath=target+"/Materials/"+(string)sm["name"]+"_URP.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(matPath);bool fresh=mat==null;if(fresh)mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.name=(string)sm["name"]+"_URP";var color=sm["baseColorFactor"].ToObject<float[]>();mat.SetColor("_BaseColor",Color.white);var bc=a["textures"].First(t=>(string)t["semantic"]=="BaseColor");var no=a["textures"].First(t=>(string)t["semantic"]=="Normal");mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>((string)bc["assetPath"]));mat.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>((string)no["assetPath"]));mat.SetFloat("_BumpScale",.35f);mat.EnableKeyword("_NORMALMAP");mat.SetFloat("_Metallic",(float)sm["metallic"]);mat.SetFloat("_Smoothness",1-(float)sm["roughness"]);if(fresh)AssetDatabase.CreateAsset(mat,matPath);else EditorUtility.SetDirty(mat);materials.Add(mat);}
 var go=new GameObject(name+"_VisualOnly");var model=AssetDatabase.LoadAssetAtPath<GameObject>(modelPath);var instance=(GameObject)PrefabUtility.InstantiatePrefab(model);instance.transform.SetParent(go.transform,false);foreach(var r in go.GetComponentsInChildren<Renderer>()){r.sharedMaterials=Enumerable.Range(0,r.sharedMaterials.Length).Select(i=>materials[Mathf.Min(i,materials.Count-1)]).ToArray();r.shadowCastingMode=ShadowCastingMode.On;r.receiveShadows=true;}var b=PlacementSession.B(go);instance.transform.position-=new Vector3(b.center.x,b.min.y,b.center.z);string prefabPath=target+"/"+name+".prefab";var prefab=PrefabUtility.SaveAsPrefabAsset(go,prefabPath);b=PlacementSession.B(go);long triangles=go.GetComponentsInChildren<MeshFilter>().Sum(x=>(long)x.sharedMesh.triangles.Length/3);UnityEngine.Object.DestroyImmediate(go);
 a["modelAssetPath"]=modelPath;a["prefabAssetPath"]=prefabPath;a["sourcePath"]="Original GLB preserved locally; SHA256 identifies source";a["fbx"]=modelPath;foreach(JObject t in a["textures"])t["path"]=t["assetPath"];foreach(JObject sm in a["materials"]){sm["BaseColor"]=a["textures"].First(t=>(string)t["semantic"]=="BaseColor")["assetPath"];sm["Normal"]=a["textures"].First(t=>(string)t["semantic"]=="Normal")["assetPath"];}Directory.CreateDirectory(PlacementSession.Root+"06.Data/AssetSources");File.WriteAllText(PlacementSession.Root+"06.Data/AssetSources/"+name+"_V001_completion.json",a.ToString());reports.Add(JObject.FromObject(new{name=name,prefab=prefabPath,model=modelPath,derivativeSha256=(string)a["fbxSha256"],triangles=triangles,boundsSize=PlacementSession.V(b.size),bottom=b.min.y,colliders=prefab.GetComponentsInChildren<Collider>().Length}));done++;File.WriteAllText(reportPath,reports.ToString());}
 AssetDatabase.SaveAssets();AssetDatabase.Refresh();return "Imported "+done+" verified models; total "+reports.Count;}
}

// [주석] 검수 자료의 작업 순서와 최신 경로표를 확인한 뒤 사용한다.
